question.solution:
class MinStack:
    def __init__(self):
        self.data = []
        self.mins = []

    def push(self, val):
        self.data.append(val)
        if not self.mins or val <= self.mins[-1]:
            self.mins.append(val)

    def pop(self):
        val = self.data.pop()
        if self.mins and self.mins[-1] == val:
            self.mins.pop()
        return val

    def top(self):
        return self.data[-1]

    def get_min(self):
        return self.mins[-1]

stack = MinStack()
stack.push(-2)
stack.push(0)
stack.push(-3)
print(stack.get_min())
print(stack.pop())
print(stack.top())
print(stack.get_min())

